import React, { useEffect, useRef } from 'react';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend, ArcElement, PointElement, LineElement } from 'chart.js';
import { Bar, Pie, Line } from 'react-chartjs-2';

ChartJS.register(
  CategoryScale,
  LinearScale,
  BarElement,
  Title,
  Tooltip,
  Legend,
  ArcElement,
  PointElement,
  LineElement
);

const Chart = ({ data, chartType, title }) => {
  const chartRef = useRef(null);

  const getChartData = () => {
    if (!data || !data.data || !Array.isArray(data.data)) {
      return {
        labels: [],
        datasets: []
      };
    }

    const labels = data.data.map(item => {
      // Get the first non-numeric key as label
      const keys = Object.keys(item);
      for (let key of keys) {
        if (typeof item[key] !== 'number') {
          return item[key];
        }
      }
      return 'Unknown';
    });

    const values = data.data.map(item => {
      // Get the first numeric key as value
      const keys = Object.keys(item);
      for (let key of keys) {
        if (typeof item[key] === 'number') {
          return item[key];
        }
      }
      return 0;
    });

    const colors = [
      'rgba(54, 162, 235, 0.8)',
      'rgba(255, 99, 132, 0.8)',
      'rgba(255, 205, 86, 0.8)',
      'rgba(75, 192, 192, 0.8)',
      'rgba(153, 102, 255, 0.8)',
      'rgba(255, 159, 64, 0.8)',
      'rgba(199, 199, 199, 0.8)',
      'rgba(83, 102, 255, 0.8)'
    ];

    return {
      labels,
      datasets: [
        {
          label: title || 'Data',
          data: values,
          backgroundColor: colors.slice(0, values.length),
          borderColor: colors.slice(0, values.length).map(color => color.replace('0.8', '1')),
          borderWidth: 2,
        }
      ]
    };
  };

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: {
        position: 'top',
      },
      title: {
        display: true,
        text: title || 'Analytics Chart',
      },
    },
    scales: chartType === 'bar' ? {
      y: {
        beginAtZero: true,
      },
    } : undefined,
  };

  const renderChart = () => {
    const chartData = getChartData();

    switch (chartType) {
      case 'bar':
        return <Bar data={chartData} options={options} />;
      case 'pie':
        return <Pie data={chartData} options={options} />;
      case 'line':
        return <Line data={chartData} options={options} />;
      default:
        return <Bar data={chartData} options={options} />;
    }
  };

  return (
    <div className="h-64 w-full">
      {renderChart()}
    </div>
  );
};

export default Chart;
